from pathlib import Path
from html import escape as e
from urllib.parse import urlencode
import json
root=Path(__file__).parent
catalog=json.loads((root/'catalog.json').read_text())
venues=catalog['venues'];sources=catalog['sources'];p=root/'site'
assert len(venues)==16 and len({v['slug'] for v in venues})==16
assert sum(v['count']>1 for v in venues)==14
assert all(v['count']==len(set(v['sourceCodes'])) for v in venues)
labels={'Eater':'Eater · Mar 2024','MND':'Mexico News Daily · Jun 2024','MexicoDesconocido':'México Desconocido','TMSeafood':'Take Me to PV · seafood','TMVersalles':'Take Me to PV · Versalles','VancouverSun':'Vancouver Sun'}
cards=[]
for i,v in enumerate(venues):
 slug=v['slug'];closed=v['researchStatus']=='CLOSED_PERMANENTLY'
 maps='https://www.google.com/maps/search/?'+urlencode({'api':1,'query':v['name']+' Puerto Vallarta','query_place_id':v['placeID']})
 directions='https://www.google.com/maps/dir/?'+urlencode({'api':1,'destination':'Puerto Vallarta','destination_place_id':v['placeID']})
 src=''.join(f'<a href="{e(sources[c]["url"])}" target="_blank" rel="noopener noreferrer">{e(labels[c])} ↗</a>' for c in v['sourceCodes'])
 if i==0:cards.append('<div class="section-heading"><p class="eyebrow">THE RECURRING FOURTEEN</p><h2>Across the city, across the reading list.</h2><p>Sorted by article appearances. Two historical picks are clearly marked closed.</p></div>')
 if v['count']==1 and venues[i-1]['count']>1:cards.append('<div class="section-heading extra"><p class="eyebrow">TWO SUPPORTING EXTRAS</p><h2>Keep room for these.</h2><p>The original guide’s one-article taco and churro stops.</p></div>')
 warning='<p class="warning closure">Listed permanently closed · historical editorial entry. Do not plan a visit unless a reopening is independently confirmed.</p>' if closed else ''
 identity=f'<details class="branch-note"><summary>Branch identity & article context</summary><p>{e(v["identityNotes"])}</p></details>' if v['identityNotes'] else ''
 cards.append(f'''<article class="card {'additional' if v['count']==1 else ''} {'is-closed' if closed else ''}" id="{slug}" data-food="{e(v['food'])}" data-time="{e('|'.join(v['meals']))}" data-neighborhood="{e(v['neighborhood'])}" data-count="{v['count']}" data-place-id="{v['placeID']}" data-research-status="{v['researchStatus']}"><div class="card-top"><span class="number">{i+1:02}</span><div><p class="eyebrow">{e(v['food'])} / {e(' + '.join(v['meals']))}</p><h2>{e(v['name'])}</h2><p class="subtitle">{e(v['subtitle'])}</p><span class="neighborhood">{e(v['neighborhood'])}</span></div><span class="count">{v['count']}<small>article{'s' if v['count']>1 else ''}</small></span></div>{warning}<div class="card-body"><div class="visual"><div class="photos" aria-label="Venue photographs"><div class="unavailable">Venue photos loading…<br><small>No stock or AI food photography.</small></div></div><a class="gallery" href="{e(maps)}" target="_blank" rel="noopener noreferrer">{'Historical listing & photo gallery' if closed else 'Real venue photos on Google Maps'} ↗</a></div><div class="story"><p>{e(v['description'])}</p><div class="order"><span class="eyebrow">{'HISTORICAL SIGNATURE · NOT A CURRENT MENU' if closed else 'YOUR FIRST ORDER'}</span><p>{e(v['signatureOrder'])}</p></div><div class="location"><span class="eyebrow">{'HISTORICAL LOCATION' if closed else 'FIND THIS BRANCH'}</span><p>{e(v['address'])}<br><small>{e(v['neighborhood'])} · Puerto Vallarta, Jalisco</small></p><a class="directions" href="{e(directions)}" target="_blank" rel="noopener noreferrer">{'Locate historical address' if closed else 'Get directions'} ↗</a></div><details class="hours" open><summary>Weekly hours · local time</summary><div class="live-hours"><p>Live schedule loading. If unavailable, <a href="{e(maps)}" target="_blank" rel="noopener noreferrer">check the listing ↗</a>.</p></div></details><p class="practical">{e(v['practicalNote'])}</p>{identity}<details class="sources"><summary>Read the {v['count']} article source{'s' if v['count']>1 else ''}</summary><div>{src}</div></details></div></div></article>''')
neighborhoods=list(dict.fromkeys(v['neighborhood'] for v in venues));options=''.join(f'<option value="{e(n)}">{e(n)}</option>' for n in neighborhoods)
reading=''.join(f'<li><a href="{e(s["url"])}">{e(labels[c])}</a></li>' for c,s in sources.items())
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Sixteen Puerto Vallarta food-guide entries across five neighborhoods: fourteen recurring editorial picks and two extras, with branch notes, live listed hours and real venue photos."><title>Puerto Vallarta · Sixteen good food stories</title><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/style.css"><script defer src="/app.js"></script></head><body><a class="skip" href="#guide">Skip to the food</a><header><a class="brand" href="/">BUEN PROVECHO <span> / A PUERTO VALLARTA FIELD GUIDE</span></a><button id="print" type="button">Save / print ↗</button></header><main><section class="intro"><p class="eyebrow">PUERTO VALLARTA, MÉXICO · A CITY-WIDE SHORTLIST</p><h1>Sixteen food stories.<br><em>More of Vallarta.</em></h1><p class="dek">From blue-corn pork-belly tacos in Versalles to steamed cabeza in Zona Romántica. Fourteen names recurring across six articles, plus the original guide’s two supporting extras.</p><div class="intro-bottom"><span>16 entries / 14 operating listings / 2 listed closed</span><a href="#guide">Find your next bite ↓</a></div></section><aside class="reader-note"><b>A reading list, not a star rating.</b> Each appearance is one vote per article, restaurant-brand-wide—not a claim that every writer visited this exact branch. The two Take Me to Puerto Vallarta articles are from the same publication and are not independent publication votes. Branches were researched 16 November 2026; closures, moves and conflicting map pins are disclosed. Hours and photos refresh below, with no “open now” claims.</aside><section class="filter-panel" aria-label="Find restaurants"><nav class="filters" aria-label="Food and time filter"><button aria-pressed="true" data-filter="All">All food & times</button><button aria-pressed="false" data-filter="Breakfast">Breakfast</button><button aria-pressed="false" data-filter="Seafood">Seafood</button><button aria-pressed="false" data-filter="Evening">Evening</button></nav><div class="select-row"><label>Neighborhood<select id="neighborhood"><option value="All">All neighborhoods</option>'''+options+'''</select></label><label>Jump to a visible entry<select id="jump"><option value="">Choose a restaurant…</option></select></label><button id="reset" type="button">Reset filters</button></div><p class="filter-help">Food/time and neighborhood combine with AND. Closed historical entries remain visible and labeled; “Evening” describes the editorial meal, not current availability.</p><p id="results" role="status">16 entries</p></section><div id="empty" hidden>No entries match both filters. Try another neighborhood or reset.</div><div id="guide">'''
foot='''</div><section class="endnote"><p class="eyebrow">A FEW USEFUL WORDS</p><h2>Order with a little confidence.</h2><div class="glossary"><p><b>Burrita</b><br>A flour-tortilla wrap; on the coast, often seafood.</p><p><b>Consommé</b><br>The savory birria broth. Ask for a cup alongside.</p><p><b>Al vapor</b><br>Steamed. At El Chulo, think tender beef-head tacos.</p></div><p>Bring small-denomination pesos as a precaution; current prices and payment methods are not independently verified. Ask about allergens and preparation. Historical article dishes are ordering ideas, not a guaranteed current menu.</p></section><footer><h2>Good food. Clear sources.</h2><p>Independent editorial descriptions, with live listing data and photographs provided by Google Maps. No sponsorship, booking links, tracking analytics or personal travel information.</p><details class="method"><summary>Method & six-article reading list</summary><p>Fourteen recurring brands plus El Carboncito and Julio’s Churros: sixteen unique entries. Ranking is one appearance per article, sorted by count, not a publication-independence score. Take Me to PV supplies two articles. Editorial branches are preferred where identifiable; El Puerco de Oro’s verified move, Marisma’s closed Versalles branch, Ocho Tostadas’ conflicting article pin and La Tía’s name/pin differences are explained on their cards. La Mucca and Memo Grill remain for provenance but are listed permanently closed; no replacement was verified.</p><ul>'''+reading+'''</ul><p>Counts are brand-wide. Tuna Azul’s two appearances are both Take Me to PV. Listing status and hours are not business-confirmed; article publication dates are older than this research. Photos are the first two returned by Google’s venue listing, not guaranteed to show both interior and food; closed-place photos are historical.</p></details><details><summary>Privacy & terms</summary><p>Tailscale access is required. No extra app account, cookies or analytics. Hosting and network providers may process IP addresses for delivery and abuse prevention. Listings/photos are requested server-side from Google; author avatars, when supplied, load from Google. External map and source links leave this guide.</p><p>Provided as-is for personal planning. Listings can change or be wrong. Photos remain their authors’ property and are displayed through Google Places, not licensed for reuse from this guide.</p><p><a href="https://policies.google.com/privacy">Google Privacy Policy</a> · <a href="https://www.google.com/help/terms_maps/">Google Maps terms</a></p></details><p class="colophon">PUERTO VALLARTA / SIX ARTICLES / EAT CURIOUSLY</p></footer></main></body></html>'''
p.joinpath('index.html').write_text(head+''.join(cards)+foot)
print(f'Built {len(venues)} unique cards: {sum(v["count"]>1 for v in venues)} recurring + {sum(v["count"]==1 for v in venues)} extras; {sum(v["researchStatus"]=="CLOSED_PERMANENTLY" for v in venues)} listed closed')
